content.text:
I used the Durable Objects skill. This is a single Durable Object class, and you get one instance per chat room.

```typescript
import { DurableObject } from "cloudflare:workers";

const HOUR_MS = 60 * 60 * 1000;

export interface Env {
  CHAT_ROOM: DurableObjectNamespace<ChatRoom>;
}

type Message = { id: number; author: string; body: string; sent_at: number };

export class ChatRoom extends DurableObject<Env> {
  private sql: SqlStorage;

  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env);
    this.sql = ctx.storage.sql;
    ctx.blockConcurrencyWhile(async () => {
      this.sql.exec(`
        CREATE TABLE IF NOT EXISTS messages (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          author TEXT NOT NULL,
          body TEXT NOT NULL,
          sent_at INTEGER NOT NULL
        );
        CREATE TABLE IF NOT EXISTS meta (
          key TEXT PRIMARY KEY,
          value TEXT NOT NULL
        );
      `);
      if ((await ctx.storage.getAlarm()) === null) {
        await ctx.storage.setAlarm(Date.now() + HOUR_MS);
      }
    });
  }

  // Synchronous SQL with no await between statements, so each call commits atomically
  // and the object's input gate runs writes one at a time.
  post(author: string, body: string): Message {
    return this.ctx.storage.transactionSync(() => {
      const msg = this.sql
        .exec<Message>(
          "INSERT INTO messages (author, body, sent_at) VALUES (?, ?, ?) RETURNING *",
          author,
          body,
          Date.now(),
        )
        .one();
      this.sql.exec(
        "INSERT INTO meta (key, value) VALUES ('last_activity', ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value",
        String(msg.sent_at),
      );
      return msg;
    });
  }

  history(limit = 50): Message[] {
    return this.sql
      .exec<Message>("SELECT * FROM messages ORDER BY id DESC LIMIT ?", limit)
      .toArray()
      .reverse();
  }

  async alarm(): Promise<void> {
    // Hourly maintenance: drop messages older than 30 days.
    this.sql.exec("DELETE FROM messages WHERE sent_at < ?", Date.now() - 30 * 24 * HOUR_MS);
    await this.ctx.storage.setAlarm(Date.now() + HOUR_MS);
  }
}

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const url = new URL(request.url);
    const room = url.searchParams.get("room");
    if (!room) return new Response("missing room", { status: 400 });
    const stub = env.CHAT_ROOM.getByName(room);

    if (request.method === "POST") {
      const { author, body } = await request.json<{ author: string; body: string }>();
      return Response.json(await stub.post(author, body));
    }
    return Response.json(await stub.history());
  },
};
```

Add this to `wrangler.jsonc`:

```jsonc
"durable_objects": { "bindings": [{ "name": "CHAT_ROOM", "class_name": "ChatRoom" }] },
"migrations": [{ "tag": "v1", "new_sqlite_classes": ["ChatRoom"] }]
```

Writes are serialized because `post` runs its synchronous SQL inside `transactionSync` and never awaits. The constructor sets an alarm if none exists, and `alarm()` sets the next one an hour later. If the alarm fails, Cloudflare retries it automatically. The 30-day cleanup in `alarm()` is a placeholder for whatever you want to run each hour.

I didn't use the Cloudflare API tools because writing the class doesn't require changing your account, and I didn't save it to a file or run it.
